parameters.jsCode:
// One request = one item in, exactly one item out.
// Output: { valid:true, customer_code, supply_type, value, request_id }
//     or: { valid:false, status, error, message }
const req = $input.first().json;

// Every error exits the same way: an array with one item.
const fail = (status, error, message) =>
  [{ json: { valid: false, status, error, message } }];

// --- 1. Authentication -------------------------------------------------
const expected = $env.WEBHOOK_API_KEY;
if (!expected) return fail(500, 'server_misconfigured', 'WEBHOOK_API_KEY is not set on the server');
// Header names are lower-cased by Node's HTTP parser.
const provided = req.headers['x-api-key'];
if (!provided || provided !== expected) return fail(401, 'unauthorized', 'Missing or invalid x-api-key header');

// --- 2. codice_cliente -------------------------------------------------
// `?.` stops if body is missing; `?? ''` makes .toString() safe.
const customerCode = (req.body?.codice_cliente ?? '').toString().trim().toUpperCase();
if (!/^CL-\d{5}$/.test(customerCode)) return fail(400, 'bad_request', 'codice_cliente is required and must match CL-00000');

// --- 3. tipo_fornitura -------------------------------------------------
// Object as lookup table: unknown key -> undefined -> falsy.
const SUPPLY_TYPES = { luce: 'electricity', electricity: 'electricity', gas: 'gas' };
const rawType = (req.body?.tipo_fornitura ?? '').toString().trim().toLowerCase();
const supplyType = SUPPLY_TYPES[rawType];
if (!supplyType) return fail(400, 'bad_request', "tipo_fornitura must be 'luce' or 'gas'");

// --- 4. valore -----------------------------------------------------------
// Check the empty string BEFORE Number(): Number('') is 0, not NaN.
const rawValue = (req.body?.valore ?? '').toString().trim().replace(',', '.');
if (rawValue === '') return fail(400, 'bad_request', 'valore is required');
const value = Number(rawValue);
// Number.isFinite rejects NaN ('abc') and Infinity in one call.
if (!Number.isFinite(value)) return fail(400, 'bad_request', 'valore must be a number');
if (value < 0) return fail(400, 'bad_request', 'valore cannot be negative');

// --- 5. conversation_id (idempotency source) ------------------------------
const conversationId = (req.body?.conversation_id ?? '').toString().trim();
if (!conversationId) return fail(400, 'bad_request', 'conversation_id is required');

// --- 6. Clean item -------------------------------------------------------
// request_id identifies the intention (same conversation, supply and value):
// a retry is a duplicate, a corrected value is a new reading.
return [{
  json: {
    valid: true,
    customer_code: customerCode,
    supply_type: supplyType,
    value,
    request_id: `${conversationId}:${supplyType}:${value}`,
  },
}];

